display.text:
use std::ffi::OsStr;
use std::fmt::Debug;
use std::path::Path;

use globset::Candidate;
use path_abs::PathAbs;

use crate::assets::{HighlightingAssets, SyntaxReferenceInSet};
use crate::error::*;
use crate::input::{OpenedInput, OpenedInputKind};

use super::{MappingEntry, MappingTarget, SyntaxMapping};

#[derive(Debug, Clone)]
pub struct IgnoredSuffixes<'a> {
    values: Vec<&'a str>,
}

impl Default for IgnoredSuffixes<'_> {
    fn default() -> Self {
        Self {
            values: vec![
                // Editor etc backups
                "~",
                ".bak",
                ".old",
                ".orig",
                // Debian and derivatives apt/dpkg/ucf backups
                ".dpkg-dist",
                ".dpkg-old",
                ".ucf-dist",
                ".ucf-new",
                ".ucf-old",
                // Red Hat and derivatives rpm backups
                ".rpmnew",
                ".rpmorig",
                ".rpmsave",
                // Build system input/template files
                ".in",
            ],
        }
    }
}

impl<'a> IgnoredSuffixes<'a> {
    pub fn add_suffix(&mut self, suffix: &'a str) {
        self.values.push(suffix)
    }

    pub(crate) fn values(&self) -> &[&'a str] {
        &self.values
    }

    pub fn strip_suffix(&self, file_name: &'a str) -> Option<&'a str> {
        for suffix in self.values.iter() {
            if let Some(stripped_file_name) = file_name.strip_suffix(suffix) {
                return Some(stripped_file_name);
            }
        }
        None
    }

    /// If we find an ignored suffix on the file name, e.g. '~', we strip it and
    /// then try again without it.
    pub fn try_with_stripped_suffix<T, F>(&self, file_name: &'a OsStr, func: F) -> Result<Option<T>>
    where
        F: Fn(&'a OsStr) -> Result<Option<T>>,
    {
        if let Some(file_str) = Path::new(file_name).to_str() {
            if let Some(stripped_file_name) = self.strip_suffix(file_str) {
                return func(OsStr::new(stripped_file_name));
            }
        }
        Ok(None)
    }

    pub(crate) fn get_syntax_for<'s>(
        &self,
        assets: &'s HighlightingAssets,
        language: Option<&str>,
        input: &mut OpenedInput<'_>,
        mapping: &SyntaxMapping<'a>,
    ) -> Result<SyntaxReferenceInSet<'s>> {
        if let Some(language) = language {
            let syntax_set = assets
                .syntax_set_cell
                .get_or_try_init(|| assets.serialized_syntax_set.deserialize())?;
            return syntax_set
                .find_syntax_by_token(language)
                .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set })
                .ok_or_else(|| Error::UnknownSyntax(language.to_owned()));
        }

        let path = input
            .metadata
            .user_provided_name
            .as_ref()
            .or(match input.kind {
                OpenedInputKind::OrdinaryFile(ref path) => Some(path),
                _ => None,
            });

        let path_syntax = if let Some(path) = path {
            let path = PathAbs::new(path)
                .map_or_else(|_| path.to_owned(), |p| p.as_path().to_path_buf());

            let match_mappings = |path: &Path| {
                let candidate = Candidate::new(path);
                let candidate_filename = path.file_name().map(Candidate::new);
                for entry in mapping.mappings().iter().rev() {
                    let entry = MappingEntry::from_tuple(entry);
                    if entry.glob_matcher().is_match_candidate(&candidate)
                        || candidate_filename.as_ref().map_or(false, |filename| {
                            entry.glob_matcher().is_match_candidate(filename)
                        })
                    {
                        return Some(*entry.target());
                    }
                }
                None
            };

            let syntax_match = match_mappings(&path);

            if let Some(MappingTarget::MapToUnknown) = syntax_match {
                Err(Error::UndetectedSyntax(path.to_string_lossy().into()))
            } else if let Some(MappingTarget::MapTo(syntax_name)) = syntax_match {
                assets
                    .find_syntax_by_name(syntax_name)?
                    .ok_or_else(|| Error::UnknownSyntax(syntax_name.to_owned()))
            } else {
                let file_name = path.file_name().unwrap_or_default();
                let mut file_name_syntax = assets.find_syntax_by_extension(Some(file_name))?;
                if file_name_syntax.is_none() {
                    if let Some(file_str) = Path::new(file_name).to_str() {
                        for suffix in self.values() {
                            if let Some(stripped_file_name) = file_str.strip_suffix(*suffix) {
                                file_name_syntax = assets.get_syntax_for_file_name(
                                    OsStr::new(stripped_file_name),
                                    &mapping.ignored_suffixes,
                                )?;
                                break;
                            }
                        }
                    }
                }

                match (file_name_syntax, syntax_match) {
                    (Some(syntax), _) => Ok(syntax),
                    (_, Some(MappingTarget::MapExtensionToUnknown)) => {
                        Err(Error::UndetectedSyntax(path.to_string_lossy().into()))
                    }
                    _ => assets
                        .get_syntax_for_file_extension(file_name, &mapping.ignored_suffixes)?
                        .ok_or_else(|| Error::UndetectedSyntax(path.to_string_lossy().into())),
                }
            }
        } else {
            Err(Error::UndetectedSyntax("[unknown]".into()))
        };

        match path_syntax {
            Err(Error::UndetectedSyntax(path)) => {
                let syntax_set = assets
                    .syntax_set_cell
                    .get_or_try_init(|| assets.serialized_syntax_set.deserialize())?;
                String::from_utf8(input.reader.first_line.clone())
                    .ok()
                    .and_then(|l| syntax_set.find_syntax_by_first_line(&l))
                    .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set })
                    .ok_or(Error::UndetectedSyntax(path))
            }
            other => other,
        }
    }
}

#[test]
fn internal_suffixes() {
    let ignored_suffixes = IgnoredSuffixes::default();

    let file_names = ignored_suffixes
        .values
        .iter()
        .map(|suffix| format!("test.json{}", suffix));
    for file_name_str in file_names {
        let file_name = OsStr::new(&file_name_str);
        let expected_stripped_file_name = OsStr::new("test.json");
        let stripped_file_name = ignored_suffixes
            .try_with_stripped_suffix(file_name, |stripped_file_name| Ok(Some(stripped_file_name)));
        assert_eq!(
            expected_stripped_file_name,
            stripped_file_name.unwrap().unwrap()
        );
    }
}

#[test]
fn external_suffixes() {
    let mut ignored_suffixes = IgnoredSuffixes::default();
    ignored_suffixes.add_suffix(".development");
    ignored_suffixes.add_suffix(".production");

    let file_names = ignored_suffixes
        .values
        .iter()
        .map(|suffix| format!("test.json{}", suffix));
    for file_name_str in file_names {
        let file_name = OsStr::new(&file_name_str);
        let expected_stripped_file_name = OsStr::new("test.json");
        let stripped_file_name = ignored_suffixes
            .try_with_stripped_suffix(file_name, |stripped_file_name| Ok(Some(stripped_file_name)));
        assert_eq!(
            expected_stripped_file_name,
            stripped_file_name.unwrap().unwrap()
        );
    }
}

